from checks import run


def test_the_walkthrough():
    """Prints the three starts, the six scales, the two saturation fractions, the dead fraction and the rules."""
    assert run() == 'start all zeros: loss after 200 steps 0.25 | hidden units identical: True\nstart four copies of one unit: loss after 200 steps 0.028 | hidden units identical: True\nstart random: loss after 200 steps 0.015 | hidden units identical: False\nscale 0.01 with tanh: activations after layers 1, 5, 10 have std 0.10, 0.00, 0.00 (vanished); the gradient reaching the input: vanished\nscale 1.0 with tanh: activations after layers 1, 5, 10 have std 0.96, 0.96, 0.96 (stable); the gradient reaching the input: exploded\nscale Xavier 0.1 with tanh: activations after layers 1, 5, 10 have std 0.62, 0.33, 0.22 (stable); the gradient reaching the input: stable\nscale 0.1 with ReLU: activations after layers 1, 5, 10 have std 0.58, 0.19, 0.04 (drifting); the gradient reaching the input: drifting\nscale 0.3 with ReLU: activations after layers 1, 5, 10 have std 1.75, 46.23, 2532.66 (exploded); the gradient reaching the input: exploded\nscale He 0.14 with ReLU: activations after layers 1, 5, 10 have std 0.83, 1.08, 1.37 (stable); the gradient reaching the input: stable\nscale 1.0 with tanh: fraction of outputs beyond 0.99, where the slope is under 0.02: 0.79\nscale 1.0 with sigmoid: fraction of inputs beyond 4, where the slope is under 0.02: 0.68\nHe weights but a bias of -5: fraction of ReLU units that never fire on 256 inputs: 0.96\nrules of thumb: tanh or sigmoid -> Xavier, 1 / sqrt(n_in) = 0.10 for 100 inputs | ReLU -> He, sqrt(2 / n_in) = 0.14 | biases -> 0\n'
